func newRole() unsafe.Pointer { return unsafe.Pointer(new(rbac.Role)) }

func newNRole(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]rbac.Role, n))) }

func ptrRole(p unsafe.Pointer, c int32) any {
	r := (*rbac.Role)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Name
	case 4:
		return &r.Description
	case 5:
		return (*string)(unsafe.Pointer(&r.CoreResponsibility))
	case 6:
		return (*[]string)(unsafe.Pointer(&r.ParentRoleIDs))
	case 7:
		return (*string)(unsafe.Pointer(&r.MaxSensitivity))
	case 8:
		return &r.IsSystem
	case 9:
		return (*string)(unsafe.Pointer(&r.CreatedBy))
	case 10:
		return &r.CreatedAt
	case 11:
		return &r.UpdatedAt
	}
	return nil
}

func valueRole(p unsafe.Pointer, c int32) any {
	r := (*rbac.Role)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Name
	case 4:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 5:
		if r.CoreResponsibility == "" {
			return nil
		}
		return string(r.CoreResponsibility)
	case 6:
		if r.ParentRoleIDs == nil {
			return []string{}
		}
		return keel.Strings(r.ParentRoleIDs)
	case 7:
		return string(r.MaxSensitivity)
	case 8:
		return r.IsSystem
	case 9:
		if r.CreatedBy == "" {
			return nil
		}
		return string(r.CreatedBy)
	case 10:
		return r.CreatedAt
	case 11:
		return r.UpdatedAt
	}
	return nil
}

func attachRole(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*rbac.Role)(p)
	switch rel {
	case 0:
		r.Permissions = append(r.Permissions, (*rbac.ResourcePermission)(child))
	}
}

func beforeCreateRole(ctx context.Context, p unsafe.Pointer) error {
	return (*rbac.Role)(p).BeforeCreate(ctx)
}

