func ptrRoleHierarchyEdge(p unsafe.Pointer, c int32) any {
	r := (*rbac.RoleHierarchyEdge)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.SeniorRoleID))
	case 2:
		return (*string)(unsafe.Pointer(&r.JuniorRoleID))
	case 3:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 4:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 5:
		return (*string)(unsafe.Pointer(&r.CreatedBy))
	case 6:
		return &r.CreatedAt
	case 7:
		return &r.UpdatedAt
	}
	return nil
}

func valueRoleHierarchyEdge(p unsafe.Pointer, c int32) any {
	r := (*rbac.RoleHierarchyEdge)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.SeniorRoleID)
	case 2:
		return string(r.JuniorRoleID)
	case 3:
		return string(r.OrganizationID)
	case 4:
		return string(r.BusinessUnitID)
	case 5:
		if r.CreatedBy == "" {
			return nil
		}
		return string(r.CreatedBy)
	case 6:
		return r.CreatedAt
	case 7:
		return r.UpdatedAt
	}
	return nil
}

func attachRoleHierarchyEdge(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*rbac.RoleHierarchyEdge)(p)
	switch rel {
	case 0:
		r.SeniorRole = (*rbac.Role)(child)
	case 1:
		r.JuniorRole = (*rbac.Role)(child)
	}
}

