func newUserRoleAssignment() unsafe.Pointer { return unsafe.Pointer(new(rbac.UserRoleAssignment)) }

func newNUserRoleAssignment(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]rbac.UserRoleAssignment, n)))
}

func ptrUserRoleAssignment(p unsafe.Pointer, c int32) any {
	r := (*rbac.UserRoleAssignment)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.RoleID))
	case 4:
		return &r.ExpiresAt
	case 5:
		return (*string)(unsafe.Pointer(&r.AssignedBy))
	case 6:
		return &r.AssignedAt
	}
	return nil
}

func valueUserRoleAssignment(p unsafe.Pointer, c int32) any {
	r := (*rbac.UserRoleAssignment)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.UserID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.RoleID)
	case 4:
		if r.ExpiresAt == nil {
			return nil
		}
		return *r.ExpiresAt
	case 5:
		if r.AssignedBy == "" {
			return nil
		}
		return string(r.AssignedBy)
	case 6:
		return r.AssignedAt
	}
	return nil
}

func attachUserRoleAssignment(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*rbac.UserRoleAssignment)(p)
	switch rel {
	case 0:
		r.Role = (*rbac.Role)(child)
	}
}

func beforeCreateUserRoleAssignment(ctx context.Context, p unsafe.Pointer) error {
	return (*rbac.UserRoleAssignment)(p).BeforeCreate(ctx)
}

